.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pOC,
    .param .u32 pKH,
    .param .u32 pKW,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pSTRH,
    .param .u32 pSTRW,
    .param .u32 pPADH,
    .param .u32 pPADW
)
{
    .reg .pred %p<12>;
    .reg .u32 %r<96>;
    .reg .u64 %rd<48>;
    .reg .s32 %s<16>;
    .reg .f32 %f<8>;
    .shared .align 16 .b8 smemW[4096];
    // Load pointers
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [b_ptr];
    ld.param.u64 %rd3, [y_ptr];
    // Load scalars
    ld.param.u32 %r10, [pN];
    ld.param.u32 %r11, [pC];
    ld.param.u32 %r12, [pH];
    ld.param.u32 %r13, [pW];
    ld.param.u32 %r14, [pOC];
    ld.param.u32 %r15, [pKH];
    ld.param.u32 %r16, [pKW];
    ld.param.u32 %r17, [pOH];
    ld.param.u32 %r18, [pOW];
    ld.param.u32 %r19, [pSTRH];
    ld.param.u32 %r20, [pSTRW];
    ld.param.u32 %r21, [pPADH];
    ld.param.u32 %r22, [pPADW];
    // Thread/block info
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %ctaid.x;
    // Precompute for cooperative weight staging and block mapping
    // wcount = C*KH*KW
    mul.lo.u32 %r64, %r11, %r15;
    mul.lo.u32 %r64, %r64, %r16;
    // ohow = OH*OW
    mul.lo.u32 %r68, %r17, %r18;
    // segments per (n, oc): S = ceil(ohow / blockDim.x)
    add.u32 %r80, %r68, %r1;
    sub.u32 %r80, %r80, 1;
    div.u32 %r81, %r80, %r1;
    // pair_index = ctaid.x / S, seg = ctaid.x % S
    div.u32 %r82, %r2, %r81;
    rem.u32 %r83, %r2, %r81;
    // Decompose pair_index into (n, oc)
    div.u32 %r27, %r82, %r14;    // n
    rem.u32 %r28, %r82, %r14;    // oc
    // Cooperative load of weights for this (oc) into shared memory
    // baseW = oc * wcount
    mul.lo.u32 %r74, %r28, %r64;
     mov.u64 %rd40, smemW;
    mov.u32 %r72, %r0;            // idx = tid
WLOAD_LOOP:
    setp.ge.u32 %p8, %r72, %r64;
    @%p8 bra WLOAD_DONE;
    add.u32 %r75, %r74, %r72;     // idx_total = baseW + idx
    mul.wide.u32 %rd41, %r75, 4;
    add.u64 %rd42, %rd1, %rd41;
    ld.global.f32 %f3, [%rd42];
    mul.wide.u32 %rd43, %r72, 4;
    add.u64 %rd44, %rd40, %rd43;
    st.shared.f32 [%rd44], %f3;
    add.u32 %r72, %r72, %r1;      // idx += blockDim.x
    bra WLOAD_LOOP;
WLOAD_DONE:
    bar.sync 0;
    // Compute per-block ohow index for this thread
    mul.lo.u32 %r84, %r83, %r1;   // seg * blockDim.x
    add.u32 %r85, %r84, %r0;      // ohow index within (OH*OW)
    setp.ge.u32 %p0, %r85, %r68;
    @%p0 bra DONE;
    // Derive ow and oh from ohow index
