    setp.ge.u32 %p5, %r33, %r16;
    @%p5 bra KH_INC;
    // siw = (ow*STRW + kw - PADW)
    mul.lo.u32 %r42, %r30, %r20;  // ow*STRW
    cvt.s32.u32 %s3, %r42;
    cvt.s32.u32 %s4, %r33;        // kw
    add.s32 %s5, %s3, %s4;
    sub.s32 %s5, %s5, %s11;       // siw
    setp.lt.s32 %p6, %s5, 0;
    @%p6 bra KW_INC;
    setp.ge.s32 %p7, %s5, %s13;
    @%p7 bra KW_INC;
    // iw_u32
    cvt.u32.s32 %r43, %s5;
    // x index: (((n*C + c)*H + ih)*W + iw)
    // t0 = n*C + c
    mul.lo.u32 %r50, %r27, %r11;
    add.u32 %r50, %r50, %r31;
    // t1 = t0*H + ih
    mul.lo.u32 %r51, %r50, %r12;
    add.u32 %r51, %r51, %r41;
    // t2 = t1*W + iw
    mul.lo.u32 %r52, %r51, %r13;
    add.u32 %r52, %r52, %r43;
    // addr_x
    mul.wide.u32 %rd12, %r52, 4;
    add.u64 %rd13, %rd0, %rd12;
    ld.global.f32 %f1, [%rd13];
    // Use shared memory weights: idx_local = ((c*KH)+kh)*KW + kw
    mul.lo.u32 %r90, %r31, %r15;
    add.u32 %r90, %r90, %r32;
    mul.lo.u32 %r90, %r90, %r16;
    add.u32 %r90, %r90, %r33;
    mul.wide.u32 %rd45, %r90, 4;
    add.u64 %rd46, %rd40, %rd45;
    ld.shared.f32 %f2, [%rd46];
    // sum += x * w
    fma.rn.f32 %f0, %f1, %f2, %f0;
KW_INC:
    add.u32 %r33, %r33, 1;
    bra KW_LOOP;
KH_INC:
    add.u32 %r32, %r32, 1;
    bra KH_LOOP;
C_NEXT:
    add.u32 %r31, %r31, 1;
    bra C_LOOP;
C_DONE:
    // y index: (((n*OC + oc)*OH + oh)*OW + ow)
    mul.lo.u32 %r60, %r27, %r14; // n*OC
    add.u32 %r60, %r60, %r28;    // + oc
    mul.lo.u32 %r61, %r60, %r17; // *OH
    add.u32 %r61, %r61, %r29;    // + oh
    mul.lo.u32 %r62, %r61, %r18; // *OW
    add.u32 %r62, %r62, %r30;    // + ow
    mul.wide.u32 %rd20, %r62, 4;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f0;
DONE:
    ret;
}
